def first_unique(values, count):
    if count <= 0:
        return []

    seen = set()
    result = []

    for value in values:
        if value not in seen:
            seen.add(value)
            result.append(value)
            if len(result) == count:
                break

    return result

def encode_frame(payload):
    if len(payload) > 65535:
        raise ValueError("Payload length exceeds 65535 bytes")
    return payload[:2].to_bytes(2, byteorder='big') + payload[2:]

def wait_microseconds(start, end):
    if not isinstance(start, (datetime.datetime, datetime.time)) or not isinstance(end, (datetime.datetime, datetime.time)):
        raise ValueError("Both inputs must be datetime.datetime or datetime.time objects")

    if isinstance(start, datetime.datetime):
        start = start.replace(tzinfo=datetime.timezone.utc)
        end = end.replace(tzinfo=datetime.timezone.utc)

    if isinstance(end, datetime.datetime):
        if start > end:
            raise ValueError("End datetime cannot be earlier than start datetime")

    start_time = start.timestamp()
    end_time = end.timestamp()

    elapsed_microseconds = int((end_time - start_time) * 1000000)

    return elapsed_microseconds

