def find_matches(records: Iterable[Dict[str, Any]], columns: Iterable[str], needle: str) -> Iterable[Dict[str, Any]]:
    needle = needle.lower()
    for record in records:
        for column in columns:
            if isinstance(record[column], str) and needle in record[column].lower():
                yield record

def pad_rows(rows, width, fill=None):
    if width < 0:
        raise ValueError("width must be non-negative")
    for row in rows:
        if not isinstance(row, list):
            raise ValueError("row must be a list")
        if len(row) > width:
            row = row[:width]
        elif len(row) < width:
            row.extend([fill] * (width - len(row)))
        yield row
